import React from 'react';
import {
  BrowserRouter as Router,
  Routes,
  Route
} from 'react-router-dom';

/* CUSTOMER */
import CustomerApp from './customer/components/CustomerApp';

/* STAFF */
import DashboardStaff from './staff/pages/DashboardStaff';
import Orders from './staff/pages/Orders'; // ✅ ADD THIS

function App() {

  return (

    <Router>

      <Routes>

        {/* CUSTOMER */}
        <Route
          path="/pastry_system/customer/*"
          element={<CustomerApp />}
        />

        {/* STAFF DASHBOARD */}
        <Route
          path="/pastry_system/staff"
          element={<DashboardStaff />}
        />

        {/* STAFF ORDERS */}
        <Route
          path="/pastry_system/staff/orders"
          element={<Orders />}
        />

      </Routes>

    </Router>

  );

}

export default App;
